import{_ as a,o as e,c as i,a4 as l}from"./chunks/framework.BybBnFXO.js";const m=JSON.parse('{"title":"净度瑕疵类型 (inclusion / blemish)","description":"","frontmatter":{"title":"净度瑕疵类型 (inclusion / blemish)","grading":"clarity-types"},"headers":[],"relativePath":"zh/grading/clarity-types.md","filePath":"zh/grading/clarity-types.md","lastUpdated":1785898160000}'),r={name:"zh/grading/clarity-types.md"};function n(s,t,d,o,h,c){return e(),i("div",null,[...t[0]||(t[0]=[l('<h1 id="净度瑕疵类型-inclusion-blemish" tabindex="-1">净度瑕疵类型 (inclusion / blemish) <a class="header-anchor" href="#净度瑕疵类型-inclusion-blemish" aria-label="Permalink to &quot;净度瑕疵类型 (inclusion / blemish)&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>宝石内含物 (inclusion) 与表面瑕疵 (blemish) 的种类、位置、数量、 可见性共同决定净度等级。同种瑕疵在不同宝石中影响不同—— 祖母绿中的&quot;花园&quot;是常态，钻石中却致命。</p><h2 id="核心要点" tabindex="-1">核心要点 <a class="header-anchor" href="#核心要点" aria-label="Permalink to &quot;核心要点&quot;">​</a></h2><ul><li>feather：羽状裂隙，最影响耐久性。</li><li>cloud：云状包体，密集时影响透明度。</li><li>crystal / mineral：结晶包裹体（金红石、锆石、方解石）。</li><li>needle：金红石针状——蓝宝石&quot;丝绒感&quot;的关键。</li><li>blemish / chip / scratch：表面瑕疵。</li><li>位置比类型更关键——亭部深处 vs 台面正中可见，影响差几倍。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>宝石</th><th>等级</th><th>备注</th></tr></thead><tbody><tr><td>emerald</td><td>jardin (3-phase)</td><td>公认美感一部分</td></tr><tr><td>ruby</td><td>silk (rutile needles)</td><td>星光效应来源</td></tr></tbody></table><p><em>详见<a href="./intro.html">分级总览</a>。</em></p>',8)])])}const p=a(r,[["render",n]]);export{m as __pageData,p as default};
